SHAPES=[
 {"id":"gable","label":"Gable","copy":"Two slopes meeting at a ridge, triangle walls at the ends. Simple, sheds snow both ways, easy to vent.","generated_in_app":True,"needs":["ridge"],"default":True},
 {"id":"shed","label":"Shed (single slope)","copy":"One slope from a tall wall to a short wall. Cheapest framing. Against a house it normally slopes AWAY from the house.","generated_in_app":False,"needs":["shed.highWallId","shed.highPlateFt","shed.lowPlateFt"],"wizard_field":"roof.params.shed"},
 {"id":"hip","label":"Hip","copy":"Slopes on all four sides, no gable walls. Stronger in wind, more cuts, hip rafters, less attic.","generated_in_app":False,"needs":["hip.faces"]},
 {"id":"half_hip","label":"Half-hip / jerkinhead","copy":"Gable with the top corner of each gable end clipped by a small hip.","generated_in_app":False,"needs":["halfHip.clipHeightFt"]},
 {"id":"dutch_gable","label":"Dutch gable (gable-on-hip)","copy":"Hip roof with a small gable on top. Looks custom, adds a valley-free little gable and more cuts.","generated_in_app":False,"needs":["dutch.gableStartFt"]},
 {"id":"saltbox","label":"Saltbox","copy":"Gable with one long low slope and one short steep slope (ridge off-center).","generated_in_app":False,"needs":["saltbox.ridgeOffsetFt","saltbox.pitchBack"]},
 {"id":"flat","label":"Flat / low-slope","copy":"Nearly flat (min 1/4 in per foot). Needs membrane (EPDM/TPO/mod-bit). Snow sits on it; needs drains or a low edge with gutter.","generated_in_app":False,"needs":["flat.slopeDirection"]},
]
TIEINS=[
 {"id":"none","label":"Freestanding (not touching the house roof)","copy":"New roof is complete on its own; only flashing/trim where it meets the house wall.","valid_shapes":["gable","shed","hip","half_hip","dutch_gable","saltbox","flat"]},
 {"id":"shed_under_eave","label":"Shed under the existing eave","copy":"New shed's high edge stops just below the house's eave; flashed up the wall. No work on the existing roof.","valid_shapes":["shed","flat"],"key_check":"highest new roof surface at the house wall <= existing eave underside - flashingClearIn"},
 {"id":"shed_into_roof_plane","label":"Shed tied into the existing roof slope","copy":"Existing eave is cut back over the addition and the new (flatter) shed roof runs up onto the existing roof until the two surfaces meet. Gives height but works on the existing roof.","valid_shapes":["shed"],"key_check":"tie line distance up the existing roof < distance to existing ridge - 1 ft"},
 {"id":"extend_plane","label":"Extend the existing roof slope","copy":"Continue the house roof at the same pitch down over the addition. Only works for shallow additions or low existing eaves far above the floor.","valid_shapes":["shed"],"key_check":"existing surface at outer wall >= lowPlateFt + heel"},
 {"id":"gable_into_roof","label":"Gable tied into the existing roof (valleys)","copy":"New gable runs out from the house with its ridge perpendicular to the house; where it meets the house roof two valleys form.","valid_shapes":["gable","half_hip"],"default_for":"gable with attachToExistingWallId set"},
 {"id":"gable_parallel_cricket","label":"Gable parallel to the house + cricket","copy":"Ridge runs along the house; the back slope drains toward the house so a cricket/saddle or a tie-in with two valleys is required.","valid_shapes":["gable","saltbox"],"warn":"ROOF_DRAINS_TO_HOUSE"},
 {"id":"hip_into_roof","label":"Hip tied into the existing roof","copy":"Hip addition with the back corners forming valleys into the house roof.","valid_shapes":["hip"]},
]
